// Copies the HTML reports generated by bazos-mcp into public/reports/ and builds src/data/reports.json
// (the catalogue the site renders). Run after every new analysis: `npm run sync`, then commit & push.
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const src = path.resolve(process.env.REPORTS_DIR ?? path.join(root, "..", "data", "reports"));
const dst = path.join(root, "public", "reports");
fs.mkdirSync(dst, { recursive: true });
fs.mkdirSync(path.join(root, "src", "data"), { recursive: true });

// the shared Férovka look, injected into every report after its own <style> (generators stay untouched)
const FONTS =
  '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' +
  '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@500;600&family=Newsreader:ital,opsz,wght@0,6..72,500;0,6..72,600;1,6..72,500&display=swap">';
const THEME = fs.readFileSync(path.join(root, "scripts", "report-theme.css"), "utf8");
const themed = (html) =>
  html.replace(/<!-- ferovka-theme -->[\s\S]*?<!-- \/ferovka-theme -->/, "").replace(
    "</head>",
    `<!-- ferovka-theme -->${FONTS}<style id="ferovka-theme">${THEME}</style><!-- /ferovka-theme -->
</head>`,
  );

const strip = (s) => s.replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
const num = (s) => Number(String(s).replace(/[^\d]/g, "")) || null;

const reports = [];
for (const file of fs.readdirSync(src).filter((f) => f.endsWith(".html"))) {
  const html = fs.readFileSync(path.join(src, file), "utf8");
  const slug = file.replace(/(-analyza)?\.html$/, "");
  const title = strip(html.match(/<title>(.*?)<\/title>/s)?.[1] ?? slug);
  const lead = strip(html.match(/<p class="lead">(.*?)<\/p>/s)?.[1] ?? "");
  const kpis = [...html.matchAll(/<div class="kpi"><div class="v">(.*?)<\/div><div class="l">(.*?)<\/div><\/div>/gs)]
    .map((m) => ({ value: strip(m[1]), label: strip(m[2]) }));
  const d = lead.match(/\((\d{1,2})\. ?(\d{1,2})\. ?(\d{4})\)/);
  const date = d
    ? `${d[3]}-${d[2].padStart(2, "0")}-${d[1].padStart(2, "0")}`
    : fs.statSync(path.join(src, file)).mtime.toISOString().slice(0, 10);
  const comparison = slug.startsWith("porovnanie");
  const name = comparison ? title : title.split(" – ")[0];
  const kpi = (re) => kpis.find((k) => re.test(k.label))?.value ?? null;
  reports.push({
    slug,
    file,
    name,
    brand: comparison ? "Porovnanie" : name.split(" ")[0],
    model: comparison ? name : name.split(" ").slice(1).join(" "),
    kind: comparison ? "comparison" : "model",
    date,
    summary: lead
      .replace(/\s*Každé auto sme porovnali.*$/, "")
      .replace(/ (na|z) auto\.bazos\.sk a www\.autobazar\.eu \([^)]*\)/, (_, p) => (p === "na" ? " na bazoši a autobazar.eu" : " z bazoša a autobazar.eu")),
    ads: num(kpis[0]?.value) ?? num(lead.match(/Porovnanie ([\d\s]+) /)?.[1]),
    median: kpi(/medián ceny/),
    r2: kpi(/vysvetlí model/),
  });
  fs.writeFileSync(path.join(dst, file), themed(html));
}
reports.sort((a, b) => (a.kind === b.kind ? 0 : a.kind === "comparison" ? -1 : 1) || b.date.localeCompare(a.date) || a.name.localeCompare(b.name, "sk"));
fs.writeFileSync(path.join(root, "src", "data", "reports.json"), JSON.stringify(reports, null, 2));
console.log(`synced ${reports.length} reports from ${src}`);
